<?php require_once __DIR__.'/../api/bootstrap.php'; require_login(); $m=current_medico(); $s=db()->prepare('SELECT id,nome FROM pacientes WHERE medico_id=? ORDER BY nome'); $s->execute([$m['id']]); $ps=$s->fetchAll(); render_header('IA de apoio'); ?><h1>IA de apoio à documentação</h1><div class="card"><p>A IA é assistiva: organiza informações fornecidas pelo médico. Não diagnostica, não escolhe CID, não determina incapacidade e não emite documentos.</p><form method="post" action="assistir.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Paciente</label><select name="paciente_id" required><option value="">Selecione</option><?php foreach($ps as $p):?><option value="<?=$p['id']?>"><?=e($p['nome'])?></option><?php endforeach;?></select><label>Texto clínico fornecido pelo médico</label><textarea name="texto" rows="14" required></textarea><label>Objetivo</label><select name="objetivo"><option>ATENDIMENTO</option><option>ATESTADO</option><option>LAUDO</option></select><br><br><button class="btn">Organizar com IA</button></form></div><?php render_footer(); ?>